// The number of the palette called `name` (Settings' palette=); 0, NIGHT, if there is none.
constexpr unsigned palette_named(std::string_view name) {
    for (unsigned n = 0; n < palettes.size(); ++n) if (name == palettes[n].name) return n;
    return 0;
}

